const u=/^(\d{4})-(0[1-9]|1[0-2])(?:-|$)/;function h(o=new Date){return`${o.getFullYear()}-${String(o.getMonth()+1).padStart(2,"0")}`}function i(o,c){var r;const e=new Map;for(const t of o){const n=(r=c(t))==null?void 0:r.match(u);if(!n)continue;const a=`${n[1]}-${n[2]}`,s=e.get(a);s?s.push(t):e.set(a,[t])}return[...e.entries()].sort(([t],[n])=>n.localeCompare(t)).map(([t,n])=>{const[a,s]=t.split("-");return{key:t,label:`${a}年${Number(s)}月`,rows:n}})}function l(o,c,e=10){const r=Math.max(1,Math.trunc(c)||1),t=Math.max(1,Math.trunc(e)||10),n=(r-1)*t;return o.slice(n,n+t)}export{h as c,i as g,l as p};
